                  "query": "query($after: String, $updatedAfter: DateTimeOrDuration) {\n  comments(first: 50, after: $after, filter: { updatedAt: { gte: $updatedAfter } }) {\n    nodes {\n      id body\n      issue { id identifier }\n      user { id name email }\n      parent { id }\n      resolvedAt\n      createdAt updatedAt editedAt\n    }\n    pageInfo { hasNextPage endCursor }\n  }\n}",
